/**
 * @name Path traversal in file operations
 * @description File operations using unsanitized paths could allow directory traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-path-traversal
 * @tags security
 *        external/cwe/cwe-22
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters that could contain user-controlled paths
    exists(DataFlow::ParameterNode param |
      source = param and
      (
        param.getParameter().getName() in ["filename", "key", "path", "filepath", "dest", "destination", "source_filename", "extra_args"]
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File system operations
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(_) and
      (
        call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "makedirs", "mkdir"]).getACall() or
        call = API::moduleImport("os").getMember("path").getMember(["join", "exists", "isfile", "isdir"]).getACall() or
        call = API::builtin("open").getACall() or
        call = API::moduleImport("shutil").getMember(["copy", "copy2", "copyfile", "move", "rmtree"]).getACall()
      )
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled path"

/**
 * @name Command injection
 * @description Executing system commands with unsanitized user input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-command-injection
 * @tags security
 *        external/cwe/cwe-78
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name SQL injection
 * @description Constructing SQL queries with unsanitized user input can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-sql-injection
 * @tags security
 *        external/cwe/cwe-89
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SqlExecution sql |
      sink = sql.getSql()
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"
